    def _assert_user_facing_markdown_labels_use_japanese_primary(
        self,
        text: str,
        *,
        source: str,
    ) -> None:
        def is_allowed_ascii_table_primary(primary: str) -> bool:
            normalized = primary.strip()
            lower_primary = normalized.lower()
            if lower_primary in _JAPANESE_PRIMARY_TABLE_CONTRACT_EXCEPTIONS:
                return True
            if lower_primary in _JAPANESE_PRIMARY_TABLE_VALUE_EXCEPTIONS:
                return True
            if re.fullmatch(
                r"(?:`[^`]+`|<[^<>]+>|[A-Z][A-Z0-9_-]*|[A-Z]{1,4}-\d+|S\d+|tc-[a-z0-9-]+)",
                normalized,
            ):
                return True
            if re.fullmatch(r"[a-z0-9._/-]+", normalized) and any(separator in normalized for separator in ("/", ".")):
                return True

            status_parts = [part.strip() for part in re.split(r"\s*/\s*", lower_primary) if part.strip()]
            if status_parts and all(part in _JAPANESE_PRIMARY_TABLE_STATUS_TOKENS for part in status_parts):
                return True

            role_parts = [part.strip() for part in re.split(r"\s*/\s*", lower_primary) if part.strip()]
            return bool(role_parts) and all(part in _JAPANESE_PRIMARY_TABLE_ROLE_TOKENS for part in role_parts)

        def assert_not_full_english_prose(line: str, *, line_number: int) -> None:
            content = line.strip()
            if not content:
                return
            if content.startswith(("#", "|", "```")):
                return
            if content.startswith(("- ", "* ", "> ")):
                content = content[2:].strip()
            elif re.match(r"^\d+[.)]\s+", content):
                content = re.sub(r"^\d+[.)]\s+", "", content)
            if content.startswith(("`", "./", "/", "[", "<")):
                return
            if (
                "New working artifacts use `./spec-dock/scripts/spec-dock new artifact <type>" in content
                and "target `artifacts/`" in content
            ):
                return
            if content == (
                "Historical creation command examples are intentionally omitted so this preservation surface "
                "is not advertised as a runnable path."
            ):
                return
            if re.search(r"[ぁ-んァ-ヶ一-龠]", content):
                return

            words = re.findall(r"[A-Za-z][A-Za-z'-]*", content)
            if len(words) < 8:
                return
            lowercase_words = [word.lower() for word in words if word.isalpha()]
            common_prose_words = {
                "a",
                "an",
                "and",
                "are",
                "as",
                "be",
                "but",
                "by",
                "does",
                "for",
                "from",
                "if",
                "in",
                "is",
                "it",
                "not",
                "of",
                "on",
                "or",
                "that",
                "the",
                "then",
                "this",
                "to",
                "with",
            }
            if sum(1 for word in lowercase_words if word in common_prose_words) < 4:
                return
            raise AssertionError(
                f"{source}:{line_number}: explanatory prose must use Japanese primary with English anchor only: {line}"
            )

        in_code_fence = False
        for line_number, line in enumerate(text.splitlines(), start=1):
            if line.strip().startswith("```"):
                in_code_fence = not in_code_fence
                continue
            if in_code_fence:
                continue

            heading_match = re.match(r"^(#{1,6})\s+(.+?)\s*$", line)
            if heading_match:
                label = heading_match.group(2)
                assert label not in _JAPANESE_PRIMARY_FORBIDDEN_HEADING_LABELS, (
                    f"{source}:{line_number}: heading must use Japanese primary with English anchor: {line}"
                )
                primary = re.split(r"\s*[（(]", label, maxsplit=1)[0].strip()
                primary_without_number = re.sub(r"^\d+[.)]\s+", "", primary)
                lower_primary = primary_without_number.lower()
                assert primary_without_number not in _JAPANESE_PRIMARY_FORBIDDEN_BARE_TOOL_TOKEN_HEADINGS, (
                    f"{source}:{line_number}: heading must use Japanese primary with tool anchor: {line}"
                )
                for phrase in _JAPANESE_PRIMARY_FORBIDDEN_PRIMARY_PHRASES:
                    assert phrase not in lower_primary, (
                        f"{source}:{line_number}: heading must keep English phrase in anchor only: {line}"
                    )
                for phrase in _JAPANESE_PRIMARY_FORBIDDEN_HEADING_PRIMARY_PHRASES:
                    assert phrase not in lower_primary, (
                        f"{source}:{line_number}: heading must use Japanese primary with English anchor: {line}"
                    )
                if any(
                    primary_without_number.startswith(prefix) for prefix in _JAPANESE_PRIMARY_HEADING_ALLOWED_PREFIXES
                ):
                    continue
                leading_tool_token = next(
                    (
                        token
                        for token in _JAPANESE_PRIMARY_HEADING_ALLOWED_TOOL_TOKENS
                        if primary_without_number == token or primary_without_number.startswith(f"{token} ")
                    ),
                    None,
                )
                if leading_tool_token is not None:
                    token_remainder = primary_without_number[len(leading_tool_token) :].strip()
                    if not token_remainder or not re.match(r"^[A-Za-z`-]", token_remainder):
                        continue
                assert not re.search(r"^[A-Za-z]", primary_without_number), (
                    f"{source}:{line_number}: heading must use Japanese primary with English anchor: {line}"
                )
                continue

            if line.startswith("|") and not re.fullmatch(r"\|[\s:-]+\|?", line):
                cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
                for cell_index, cell in enumerate(cells, start=1):
                    if not cell or cell.startswith("`"):
                        continue
                    primary = re.split(r"\s*[（(]", cell, maxsplit=1)[0].strip()
                    lower_primary = primary.lower()
                    for phrase in _JAPANESE_PRIMARY_FORBIDDEN_PRIMARY_PHRASES:
                        assert phrase not in lower_primary, (
                            f"{source}:{line_number}: table label must keep English phrase in anchor only: {line}"
                        )
                    if not re.match(r"^[a-z]", lower_primary):
                        continue
                    assert is_allowed_ascii_table_primary(primary), (
                        f"{source}:{line_number}: table label must use Japanese primary "
                        "unless it is an explicit contract/code/path/status/role value "
                        f"(cell {cell_index}: {cell!r}): {line}"
                    )
                continue

            assert_not_full_english_prose(line, line_number=line_number)

    def _assert_concrete_test_cases_nested_list_contract(self, text: str, *, source: str) -> None:
        marker = "#### 具体テストケース一覧"
        assert marker in text, f"{source} must include concrete test case section"
        section = text.split(marker, 1)[1]
        section_end_candidates = [
            index
            for index in (
                section.find("\n#### "),
                section.find("\n## "),
            )
            if index != -1
        ]
        if section_end_candidates:
            section = section[: min(section_end_candidates)]
        assert not re.search(r"(?m)^\|.*\|$", section), (
            f"{source} concrete test case section must not contain table rows"
        )
        case_pattern = re.compile(
            r"(?m)^- `tc-s\d{2}-\d{3}` [^\n:]+: .+\n"
            r"(?:  - .+\n)+"
        )
        case_blocks = case_pattern.findall(section)
        assert len(case_blocks) >= 2, f"{source} must include at least two concrete nested test case examples"
        require_related_closure_id = len(case_blocks) > 1
        for case_block in case_blocks:
            assert re.search(r"(?m)^- `tc-s\d{2}-\d{3}` [^:]+: .+$", case_block), (
                f"{source} concrete case must start with a backticked concrete test case id bullet"
            )
            standard_labels_present = all(
                re.search(rf"(?m)^  - {label}:[ \t]*\S.*$", case_block)
                for label in ("前提", "操作", "期待結果", "失敗検出", "検証方法")
            )
            alternative_labels_present = all(
                re.search(rf"(?m)^  - {label}:[ \t]*\S.*$", case_block)
                for label in ("テスト不要理由", "代替検証方法", "期待結果", "記録先")
            )
            assert standard_labels_present or alternative_labels_present, (
                f"{source} concrete case must include standard test labels "
                f"or inspect/manual alternative labels: {case_block}"
            )
            if require_related_closure_id:
                assert re.search(r"(?m)^  - 関連 closure id: .+", case_block), (
                    f"{source} multi-case section must map each case to related closure id: {case_block}"
                )
            assert not re.search(r"(?m)^\|.*\|$", case_block), (
                f"{source} concrete case must not use a table row: {case_block}"
            )

    def _assert_delegated_draft_evidence_schema_contract(self, text: str, *, source: str) -> None:
        for state in (
            "requested",
            "produced",
            "integrated",
            "partially_integrated",
            "rejected",
            "superseded",
            "blocked",
            "stale",
        ):
            assert state in text, f"{source}: missing lifecycle state {state}"
        ineligible_rule_pattern = re.compile(
            r"(?:Promotion-ineligible states:[\s\S]{0,160}"
            r"stale[\s\S]{0,160}rejected[\s\S]{0,160}superseded[\s\S]{0,160}blocked"
            r"|昇格不可 state:[\s\S]{0,160}"
            r"stale[\s\S]{0,160}rejected[\s\S]{0,160}superseded[\s\S]{0,160}blocked"
            r"|stale[\s\S]{0,80}rejected[\s\S]{0,80}superseded[\s\S]{0,80}blocked"
            r"[\s\S]{0,80}promotion evidence に使えない)"
        )
        assert re.search(ineligible_rule_pattern, text), (
            f"{source}: missing explicit promotion-ineligible rule for stale/rejected/superseded/blocked"
        )
        for field in (
            "role",
            "phase",
            "scope",
            "authorization source",
            "source artifacts",
            "draft artifact path",
            "status",
            "integration result",
            "rejected portions",
            "blockers",
            "reviewer result",
            "promotion decision",
        ):
            assert field in text, f"{source}: missing delegated evidence field {field}"
        for field in (
            "created_by_role",
            "scope_id",
            "source_paths",
            "intended_targets",
            "adoption_status: unreviewed",
            "reflected_to: []",
            "diff_guard_result",
            "fallback decision",
            "report evidence destination",
            "Evidence Adoption Ledger fields",
        ):
            assert field in text, f"{source}: missing delegated artifact evidence field {field}"
        assert "artifacts/" in text, f"{source}: missing artifacts/ delegated draft output guidance"
        assert "legacy `discussions/`" in text or "`discussions/` は legacy / preservation evidence" in text, (
            f"{source}: missing legacy discussions historical evidence guidance"
        )
        assert "grandfathered evidence" in text, f"{source}: missing grandfathered evidence wording"
        for retired_heavy_field in (
            "manifest_hash",
            "permission_profile_name",
            "permission_profile_hash",
            "write_session_invocation_hash",
            "probe_run_id",
            "task manifest path/hash",
            "input authority path/hash",
            "session invocation path/hash",
        ):
            assert retired_heavy_field not in text, (
                f"{source}: retired manifest-heavy field must not be standard delegated draft evidence {retired_heavy_field}"
            )
        for retired_grant_key in (
            "can_write_requirement",
            "can_write_design",
            "can_write_plan",
            "can_write_report",
            "can_write_discussions",
            "can_write_implementation",
            "can_mark_issue_ready",
            "can_finish_issue",
            "can_complete_phase",
        ):
            assert retired_grant_key not in text, (
                f"{source}: retired grant key must not appear in authority schema {retired_grant_key}"
            )
        for invalid_wildcard in ("`*`", "`grants.*`", "`all`"):
            assert invalid_wildcard in text, f"{source}: missing invalid wildcard token {invalid_wildcard}"
        for field, alternatives in (
            ("expected verdict", ("expected verdict", "期待される判定")),
            ("allowed next action", ("allowed next action", "許可される次アクション")),
            ("report evidence path", ("report evidence path", "report 証跡の記録先", "レポート証跡の記録先")),
            ("promotion eligibility", ("promotion eligibility", "昇格可否")),
        ):
            assert any(alternative in text for alternative in alternatives), (
                f"{source}: missing failure-mode field {field}"
            )
        expected_failure_mode_rows = {
            "missing workflow-scoped authorization evidence": (
                "blocked / incomplete",
                (
                    "record workflow request authorization source and boundary or use manual authoring",
                    "ワークフロー利用依頼の authorization source と boundary を記録する、または手動 authoring に戻す",
                    "ワークフロー利用依頼の authorization source と boundary を記録する、または手動 authoring を使う",
                ),
            ),
            "missing/stale previous reviewer pass": (
                "blocked / incomplete",
                (
                    "rerun reviewer gate",
                    "reviewer gate を再実行する",
                    "レビューゲートを再実行する（rerun reviewer gate）",
                    "rerun reviewer gate（reviewer gate を再実行する）",
                ),
            ),
            "requirement gap during design": (
                "blocked / incomplete",
                (
                    "return to requirement phase",
                    "requirement phase へ戻す",
                    "return to requirement phase（requirement phase に戻す）",
                ),
            ),
            "design gap during plan": (
                "blocked / incomplete",
                (
                    "return to design phase",
                    "design phase へ戻す",
                    "return to design phase（design phase に戻す）",
                ),
            ),
            "role unavailable": (
                "blocked / manual path",
                (
                    "record unavailable and continue manually if valid",
                    "利用不可を記録し、妥当なら手動で続行する",
                    "record unavailable and continue manually if valid（利用不可を記録し、妥当なら手動で継続する）",
                ),
            ),
            "forbidden action attempt": (
                "rejected",
                (
                    "discard draft and record incident",
                    "ドラフトを破棄し incident を記録する",
                    "discard draft and record incident（draft を破棄し、incident を記録する）",
                ),
            ),
            "stale draft": (
                "stale",
                (
                    "regenerate or reconcile",
                    "再生成または差分調整する",
                    "regenerate or reconcile（再生成または整合する）",
                ),
            ),
            "superseded draft": (
                "superseded",
                (
                    "reference replacement draft",
                    "置換先ドラフトを参照する",
                    "reference replacement draft（置換後 draft を参照する）",
                ),
            ),
            "missing draft evidence when delegated use is claimed": (
                "incomplete",
                (
                    "add evidence or remove delegated-use claim",
                    "証跡を追加する、または委任使用 claim を外す",
                    "add evidence or remove delegated-use claim（証跡を追加する、または委任利用 claim を削除する）",
                ),
            ),
            "reviewer unavailable/denied/waived/provisional": (
                "blocked / incomplete",
                (
                    "obtain fresh passed reviewer or record risk acceptance without promotion",
                    "fresh な passed reviewer を取得する、または昇格なしの risk acceptance を記録する",
                    "obtain fresh passed reviewer or record risk acceptance without promotion（fresh passed reviewer を取得する、または昇格なしの risk acceptance を記録する）",
                ),
            ),
        }
        table_rows = {}
        for line in text.splitlines():
            if not line.startswith("|") or line.startswith("|---"):
                continue
            cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
            if len(cells) == 5:
                table_rows[cells[0]] = cells
        for failure_mode, (expected_verdict, expected_next_actions) in expected_failure_mode_rows.items():
            matching_keys = [
                key
                for key in table_rows
                if key == failure_mode or key.startswith(f"{failure_mode}（") or key.endswith(f"（{failure_mode}）")
            ]
            assert matching_keys, f"{source}: missing failure-mode table row {failure_mode}"
            cells = table_rows[matching_keys[0]]
            assert cells[1] == expected_verdict, f"{source}: unexpected verdict for failure mode {failure_mode}"
            assert cells[2] in expected_next_actions, (
                f"{source}: unexpected next action for failure mode {failure_mode}"
            )
            assert cells[3], f"{source}: missing report evidence path for failure mode {failure_mode}"
            assert cells[4] == "ineligible", (
                f"{source}: unexpected promotion eligibility for failure mode {failure_mode}"
            )

    def _assert_checked_in_dogfooding_mirror_docs_match_provider_assets(self, repo_root: Path) -> None:
        for mirror_rel_path, asset_rel_path in self._DOGFOODING_MIRROR_PROVIDER_ASSET_MAP.items():
            mirror_path = repo_root / mirror_rel_path
            asset_path = repo_root / asset_rel_path
            assert mirror_path.is_file(), f"missing checked-in dogfooding mirror file: {mirror_path}"
            assert asset_path.is_file(), f"missing provider asset file: {asset_path}"
            assert mirror_path.read_bytes() == asset_path.read_bytes(), (
                f"checked-in dogfooding mirror file diverged from provider asset: {mirror_rel_path}"
            )

    def _assert_checked_in_dogfooding_active_none_reports_match_provider_assets(
        self,
        repo_root: Path,
    ) -> None:
        for mirror_rel_path, asset_rel_path in self._DOGFOODING_ACTIVE_NONE_REPORT_PROVIDER_ASSET_MAP.items():
            mirror_path = repo_root / mirror_rel_path
            asset_path = repo_root / asset_rel_path
            assert mirror_path.is_file(), f"missing checked-in active-none report mirror: {mirror_path}"
            assert asset_path.is_file(), f"missing provider active-none report asset: {asset_path}"
            assert mirror_path.read_text(encoding="utf-8") == asset_path.read_text(encoding="utf-8"), (
                f"checked-in active-none report mirror diverged from provider asset: {mirror_rel_path}"
            )

    def _assert_checked_in_dogfooding_runtime_mirror_match_provider_assets(self, repo_root: Path) -> None:
        provider_root = repo_root / "src" / "spec_dock" / "assets" / "spec_dock" / "scripts" / "spec_dock_runtime"
        mirror_root = repo_root / "spec-dock" / "scripts" / "spec_dock_runtime"
        assert provider_root.is_dir(), f"missing provider runtime asset directory: {provider_root}"
        assert mirror_root.is_dir(), f"missing checked-in dogfooding runtime mirror directory: {mirror_root}"
        provider_inventory = self._runtime_inventory(provider_root)
        mirror_inventory = self._runtime_inventory(mirror_root)

        provider_paths = set(provider_inventory)
        mirror_paths = set(mirror_inventory)
        assert mirror_paths == provider_paths, (
            "checked-in dogfooding runtime mirror inventory diverged from provider assets: "
            f"missing={sorted(provider_paths - mirror_paths)} extra={sorted(mirror_paths - provider_paths)}"
        )

        for rel_path in sorted(provider_paths):
            mirror_path = mirror_inventory[rel_path]
            asset_path = provider_inventory[rel_path]
            assert mirror_path.read_bytes() == asset_path.read_bytes(), (
                f"checked-in dogfooding runtime mirror file diverged from provider asset: {rel_path}"
            )

