    def test_issue_174_pr_observation_wait_preserves_output_boundary_and_line_budget(self) -> None:
        forbidden_tokens = (
            "https://example.test",
            "alice",
            "CI Workflow",
            "unit-test-job",
            "Run tests",
            "P1",
            "body must stay hidden",
        )
        scenario = [
            {
                "ci": "failed",
                "review": "changes_requested",
                "check_runs": {"total": 2, "success": 1, "failed": 1},
                "failures": [
                    {
                        "workflow_name": "CI Workflow",
                        "job_name": "unit-test-job",
                        "html_url": "https://example.test/job/1",
                        "failed_steps": [{"name": "Run tests", "conclusion": "failure"}],
                    }
                ],
                "signals": [
                    {
                        "kind": "pull_review",
                        "id": 201,
                        "author": "alice",
                        "state": "changes_requested",
                        "body": "P1 body must stay hidden",
                    }
                ],
                "threads": {"total": int("9" * 180), "unresolved": int("8" * 180), "items": []},
                "review_requests": [{"login": "reviewer"} for _ in range(40)],
                "limitations": [{"code": f"limit_{index}", "severity": "informational"} for index in range(30)],
            }
        ]
        with tempfile.TemporaryDirectory() as tmp_dir:
            result, _out_dir = self._issue_174_run_wait_fake_snapshots(
                Path(tmp_dir),
                scenario,
                timeout_seconds=2,
                same_fingerprint_count=1,
            )
            assert result.returncode == 0, result.stdout + result.stderr
            json.loads(result.stdout)
            stderr_line = result.stderr.strip()
            assert len(stderr_line) <= 240
            assert "limit=truncated" in stderr_line
            assert "ci=failed" in stderr_line
            assert "fail=1" in stderr_line
            for token in forbidden_tokens:
                assert token not in result.stderr

        with tempfile.TemporaryDirectory() as tmp_dir:
            quiet_result, _quiet_out_dir = self._issue_174_run_wait_fake_snapshots(
                Path(tmp_dir),
                scenario,
                progress="none",
                timeout_seconds=2,
                same_fingerprint_count=1,
            )
            assert quiet_result.returncode == 0, quiet_result.stdout + quiet_result.stderr
            json.loads(quiet_result.stdout)
            assert quiet_result.stderr == ""

    def test_issue_75_pr_observation_wait_requires_quiet_and_same_fingerprint(self) -> None:
        repo_root = Path(__file__).resolve().parents[3]
        script_path = (
            repo_root
            / "src/spec_dock/assets/install_root/.agents/skills/github-pr-observation/scripts/wait_pr_observation.sh"
        )

        with tempfile.TemporaryDirectory() as tmp_dir:
            tmp_path = Path(tmp_dir)
            fake_bin = tmp_path / "bin"
            fake_bin.mkdir()
            fake_gh = fake_bin / "gh"
            scenario_path = tmp_path / "scenario.json"
            state_path = tmp_path / "state.txt"
            scenario_path.write_text(
                json.dumps([
                    {"head": "a" * 40, "ci": "passed", "review": "approved"},
                    {"head": "a" * 40, "ci": "passed", "review": "approved"},
                ]),
                encoding="utf-8",
            )
            self._issue_75_write_pr_observation_wait_fake_gh(
                fake_gh,
                scenario_path=scenario_path,
                state_path=state_path,
            )
            env = {
                **os.environ,
                "PATH": f"{fake_bin}{os.pathsep}{os.environ.get('PATH', '')}",
                "GH_FAKE_WAIT_SCENARIO": str(scenario_path),
                "GH_FAKE_WAIT_STATE": str(state_path),
            }

            result = subprocess.run(
                [
                    str(script_path),
                    "--repo",
                    "owner/repo",
                    "--pr",
                    "13",
                    "--head-sha",
                    "a" * 40,
                    "--trigger-mode",
                    "resume",
                    "--trigger-comment-id",
                    "99",
                    "--trigger-created-at",
                    "2026-06-08T01:00:00Z",
                    "--timeout-seconds",
                    "2",
                    "--poll-interval-seconds",
                    "1",
                    "--quiet-seconds",
                    "90",
                    "--same-fingerprint-count",
                    "2",
                ],
                env=env,
                capture_output=True,
                text=True,
                check=False,
            )

            assert result.returncode == 0, result.stdout + result.stderr
            payload = json.loads(result.stdout)
            assert payload["summary"]["ci"] == "passed"
            assert payload["summary"]["review"] == "approved"
            assert payload["observation_complete"] is False
            assert payload["normalized_status"] == "timeout"
            assert payload["wait"]["same_fingerprint_observed"] >= 1
            timeout_limitation = next(
                item for item in payload["limitations"] if item["code"] == "snapshot_poll_timeout"
            )
            assert timeout_limitation["source"] in {
                "wait_pr_observation.sh",
                "fetch_pr_observation_snapshot.sh",
            }
            if timeout_limitation["source"] == "wait_pr_observation.sh":
                assert timeout_limitation["deadline_reached"] is True

